import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)
    threads = []

    def run_command(file_path, index):
        try:
            result = subprocess.run(file_path, shell=True)
            exit_codes[index] = result.returncode
        except Exception:
            exit_codes[index] = -1

    for i, file in enumerate(file_list):
        thread = threading.Thread(target=run_command, args=(file, i))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

