import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found at {script_path}")

    process = subprocess.Popen(script_path, shell=True)
    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    accumulated_cpu = 0.0
    accumulated_mem = 0
    start_time = time.time()

    while process.poll() is None:
        if time.time() - start_time > timeout:
            process.terminate()
            break
        try:
            accumulated_cpu += ps_process.cpu_percent(interval=None)
            accumulated_mem += ps_process.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        time.sleep(0.1)

    return {
        'CPU Usage': accumulated_cpu,
        'Memory Usage': accumulated_mem
    }

import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR)

    files = glob.glob(pattern)
    archive_file = os.path.join(ARCHIVE_DIR, 'archive.tar.gz')

    if files:
        files_str = ' '.join(files)
        subprocess.run(f"tar -czf {archive_file} {files_str}", shell=True)
        for file_path in files:
            if os.path.isfile(file_path):
                os.remove(file_path)

    return archive_file

